// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

export interface LoginIn {
  username: string;
  password: string;
  /** Optional terminal name shown in session lists */
  terminal_label?: string | null;
}

export interface LoginOut {
  access_token: string;
  /** Always bearer */
  token_type: string;
  /** Access token lifetime in seconds */
  expires_in: number;
  refresh_token: string;
  refresh_expires_in: number;
  user: MeOut;
  /** Show `message` as a banner while `state` is grace or locked */
  license: LicenseStatusOut;
}

export interface MeOut {
  user_id: number;
  username: string;
  display_name: string;
  /** Null for accounts without an employee (e.g. the bootstrap Super Admin) */
  employee_id: number | null;
  emp_number: string | null;
  designation: string | null;
  department: string | null;
  roles: string[];
  permissions: string[];
  workspaces: WorkspaceOut[];
  must_change_password: boolean;
  preferences: PreferencesOut;
}

export interface WorkspaceOut {
  code: string;
  label: string;
  label_ur: string;
  description: string;
  /** The user's roles that open this workspace */
  roles: string[];
}

/** Display preferences and the user's own UI state (`preferences.extra`). */
export interface PreferencesOut {
  theme: "Light" | "DarkHighContrast";
  language: "en" | "ur";
  ui_scale_pct: number;
  /** Separate (a download button per document) or Combined (one PDF) for a set of documents */
  pdf_download: "Separate" | "Combined";
  /** The user's own UI state (PUT /settings/me extra), as saved */
  extra: Record<string, unknown>;
}

/** The server's license state (licensing.public_view): no hardware details. */
export interface LicenseStatusOut {
  state: "ok" | "grace" | "locked" | "dev";
  reason:
    | "hardware_changed"
    | "license_missing"
    | "license_invalid"
    | "license_outdated"
    | "license_expired"
    | "hardware_unreadable"
    | "check_failed"
    | "standby_main_active"
    | "standby_check_failed"
    | "standby_invalid"
    | null;
  /** One sentence for people: show it as the banner */
  message: string;
  hospital: string | null;
  license_id: string | null;
  grace_until: string | null;
  days_left: number | null;
  expires_at: string | null;
  /** A milder warning (e.g. the license ends within 30 days), even when ok */
  notice: string | null;
  vendor: VendorContactOut;
  logins: "all" | "super_admin_only";
}

/** The vendor to contact about the license (only the channels the vendor gave are present). */
export interface VendorContactOut {
  company: string;
  phone?: string | null;
  whatsapp?: string | null;
  email?: string | null;
  website?: string | null;
}

/** This terminal's location, printers and cash node. The location and printer fields are present only when `registered` is true; `hint` only when it is false. */
export interface TerminalIdentityOut {
  registered: boolean;
  client_ip: string | null;
  mac: string | null;
  hint?: string | null;
  location_label?: string | null;
  cash_node?:
    | "MainReception"
    | "PharmacyCounter"
    | "LabReception"
    | "IPDBilling"
    | "EmergencyCounter"
    | "CashierDesk"
    | null;
  ip?: string | null;
  receipt_printer?: string | null;
  receipt_printer_address?: string | null;
  receipt_paper_mm?: number | null;
  label_printer?: string | null;
  label_printer_address?: string | null;
  document_printer?: string | null;
  document_printer_address?: string | null;
  card_printer?: string | null;
  card_printer_address?: string | null;
}

export interface ChangePasswordIn {
  current_password: string;
  new_password: string;
}

export interface TokenPair {
  access_token: string;
  /** Always bearer */
  token_type: string;
  /** Access token lifetime in seconds */
  expires_in: number;
  refresh_token: string;
  refresh_expires_in: number;
}

/** Log in (returns tokens, profile, roles, workspaces) — POST /api/v1/auth/login (permissions: any logged-in user). */
export function login(body: LoginIn): Promise<LoginOut> {
  return api<LoginOut>("POST", `/auth/login`, body);
}

/** Identify this terminal (location + mapped printers) — works before login — GET /api/v1/terminals/whoami (permissions: any logged-in user). */
export function whoami(): Promise<TerminalIdentityOut> {
  return api<TerminalIdentityOut>("GET", `/terminals/whoami`, undefined);
}

/** Change own password — POST /api/v1/auth/change-password (permissions: any logged-in user). */
export function changePassword(body: ChangePasswordIn): Promise<TokenPair> {
  return api<TokenPair>("POST", `/auth/change-password`, body);
}

/** The server's license state: show a banner when it needs attention — works before login — GET /api/v1/meta/license (permissions: any logged-in user). */
export function licenseStatus(): Promise<LicenseStatusOut> {
  return api<LicenseStatusOut>("GET", `/meta/license`, undefined);
}
